mapper.select:
select id, task_id, device_sn, attitude_head, attitude_pitch, attitude_roll, height, latitude, longitude, mode_code, track_id, publish_time from device_telemetry_sub where is_deleted = 0 and publish_time is not null
and task_id = #{taskId}
and publish_time >= #{publishTimeStart}
and publish_time <= #{publishTimeEnd}
order by publish_time asc, id asc
